sys_script_include.script:
var VendorRiskUtils = Class.create();
VendorRiskUtils.prototype = {

    calculateRiskScore: function(vendorSysId) {

        var score = 0;

        var vendorGR = new GlideRecord('x_cdltd_vendor_o_0_vendor_request');
        if (!vendorGR.get(vendorSysId))
            return null;

        // Restricted Country
        if (vendorGR.country == 'Restricted')
            score += 40;

        // Annual Contract Value > 5 million
        if (parseFloat(vendorGR.annual_contract_value) > 5000000)
            score += 20;

        // Consulting category
        if (vendorGR.category == 'Consulting')
            score += 10;

        // Missing documents
        var docCount = 0;

        var docGR = new GlideRecord('x_cdltd_vendor_o_0_vendor_document');
        docGR.addQuery('vendor_request', vendorSysId);
        docGR.addQuery('received', false);
        docGR.query();

        while (docGR.next()) {
            docCount++;
        }

        score += Math.min(docCount * 10, 30);

        var level = 'Low';

        if (score >= 60)
            level = 'High';
        else if (score >= 30)
            level = 'Medium';

        return {
            score: score,
            level: level
        };
    },

    type: 'VendorRiskUtils'
};
